-- One-time owner-authorized demo setup. NOT a schema migration.
-- Executes only for an empty, uniquely named Retail Demo subscription.
begin;
do $$ begin
 assert (select count(*)=1 from public.subscriptions where name='Retail Demo' and slug='retail-demo'),'Retail Demo identity is ambiguous';
 assert (select count(*)=0 from public.products where subscription_id=(select id from public.subscriptions where name='Retail Demo' and slug='retail-demo')),'Demo already contains products; stop instead of overwriting';
 assert (select count(*)=0 from public.orders where subscription_id=(select id from public.subscriptions where name='Retail Demo' and slug='retail-demo')),'Demo already contains orders; stop instead of overwriting';
end $$;
select set_config('demo.sid',(select id::text from public.subscriptions where name='Retail Demo' and slug='retail-demo'),true);
select set_config('request.jwt.claim.sub',(select user_id::text from public.memberships where subscription_id=current_setting('demo.sid')::uuid and role='owner'),true);
set local role authenticated;
update public.locations set name='Main Store',address='100 Example Avenue, Demo City, WA 00000 (fictional)',phone='202-555-0101',hours='Mon–Sat 10 am–6 pm; Sun 11 am–4 pm · Demo hours',published=true
where subscription_id=current_setting('demo.sid')::uuid and name='Retail Demo';
insert into public.locations(subscription_id,name,address,phone,hours,published) values
(current_setting('demo.sid')::uuid,'Market Annex','200 Example Lane, Demo City, WA 00000 (fictional)','202-555-0102','Tue–Sat 10 am–5 pm · Demo hours',true),
(current_setting('demo.sid')::uuid,'Studio (unpublished)','300 Example Court, Demo City, WA 00000 (fictional)','202-555-0103','Private demo workspace',false);
update public.subscriptions set description='A fictional shop for useful, thoughtfully chosen everyday goods. Browse stationery, home accents, bags and small gifts. This is a demonstration business: all products, locations and orders are samples; payments are simulated.',accent='#b88656',header_layout='centered',header_identity='name',header_background='#ffffff',storefront_text='#173b35',storefront_button='#173b35',storefront_font='sans',storefront_text_size='standard',tile_corners='subtle',tile_spacing='comfortable',
default_location_id=(select id from public.locations where subscription_id=current_setting('demo.sid')::uuid and name='Main Store'),
logo_url='https://talix-git-feature-core-storefront-visual-shopping-bravokelo.vercel.app/demo-retail/logo.svg',
header_photo_url='https://talix-git-feature-core-storefront-visual-shopping-bravokelo.vercel.app/demo-retail/header.svg'
where id=current_setting('demo.sid')::uuid;
insert into public.products(subscription_id,location_id,name,description,price_cents,image_url,available,options,category)
select current_setting('demo.sid')::uuid,
case when item->>'location'='shared' then null else (select id from public.locations where subscription_id=current_setting('demo.sid')::uuid and name=case item->>'location' when 'main' then 'Main Store' else 'Market Annex' end) end,
item->>'name',item->>'description',(item->>'price_cents')::integer,
case when item->>'asset' is null then null else 'https://talix-git-feature-core-storefront-visual-shopping-bravokelo.vercel.app/demo-retail/'||(item->>'asset') end,
(item->>'available')::boolean,item->'options',item->>'category'
from jsonb_array_elements($catalog$[{"name": "Everyday Notebook", "category": "Desk & Paper", "price_cents": 1800, "description": "Deep green cloth cover, 160 lined pages and a ribbon marker. A simple place for notes, ideas and everyday lists.", "asset": "everyday-notebook.svg", "location": "shared", "available": true, "options": [{"id": "gift_wrap", "name": "Gift wrapping", "price_cents": 400}]}, {"name": "Weekly Desk Planner", "category": "Desk & Paper", "price_cents": 2200, "description": "An undated weekly planner with room for appointments, priorities and small reminders. Start any week of the year.", "asset": "weekly-desk-planner.svg", "location": "shared", "available": true, "options": [{"id": "gift_wrap", "name": "Gift wrapping", "price_cents": 400}]}, {"name": "Brass Writing Pen", "category": "Desk & Paper", "price_cents": 1600, "description": "A balanced refillable writing pen with a warm brass finish and a smooth black ink refill.", "asset": "brass-writing-pen.svg", "location": "shared", "available": true, "options": [{"id": "gift_wrap", "name": "Gift wrapping", "price_cents": 400}]}, {"name": "Canvas Pencil Case", "category": "Desk & Paper", "price_cents": 1400, "description": "A compact zip case for pens, pencils and small desk essentials. Soft canvas with a sturdy cotton lining.", "asset": "canvas-pencil-case.svg", "location": "shared", "available": true, "options": [{"id": "gift_wrap", "name": "Gift wrapping", "price_cents": 400}]}, {"name": "Everyday Canvas Tote", "category": "Everyday Carry", "price_cents": 2800, "description": "A roomy cotton canvas tote with comfortable handles and an inside pocket. Built for daily errands and all the small things you carry.", "asset": "everyday-canvas-tote.svg", "location": "shared", "available": true, "options": [{"id": "gift_wrap", "name": "Gift wrapping", "price_cents": 400}]}, {"name": "Pocket Zip Pouch", "category": "Everyday Carry", "price_cents": 1200, "description": "Keep keys, coins and little essentials